dark.customCSS:
:root {
	--gem-glass: color-mix(in oklab, var(--color-gray-900) 72%, transparent);
	--gem-sidebar: color-mix(in oklab, var(--color-gray-950) 78%, transparent);
	--gem-bubble: color-mix(in oklab, var(--color-gray-800) 72%, transparent);
	--gem-selected: color-mix(in oklab, var(--color-gray-600) 30%, transparent);
	--gem-line: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--gem-facet: color-mix(in oklab, var(--color-gray-200) 9%, transparent);
	--gem-shade: color-mix(in oklab, black 70%, transparent);
	--gem-accent: #fda0a3;
	--gem-glow: color-mix(in oklab, #ed737b 60%, transparent);
	--gem-ring: color-mix(in oklab, #ed737b 18%, transparent);
	--gem-mark: color-mix(in oklab, #d15a63 38%, transparent);
}

/* Cut-stone surfaces in Open WebUI's own shapes: a lit top facet, a ring
   in the stone's color on focus. !important only where a gradient clears
   the background first. */
#message-input-container {
	background-color: var(--gem-glass) !important;
	border-color: var(--gem-line) !important;
	backdrop-filter: blur(16px) saturate(1.2);
	box-shadow: inset 0 1px 0 var(--gem-facet), 0 12px 36px -18px var(--gem-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--gem-glow) !important;
	box-shadow: inset 0 1px 0 var(--gem-facet), 0 0 0 3px var(--gem-ring), 0 12px 36px -18px var(--gem-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--gem-bubble) !important;
	box-shadow: inset 0 0 0 1px var(--gem-line), inset 0 1px 0 var(--gem-facet);
}
#sidebar {
	background-color: var(--gem-sidebar) !important;
	backdrop-filter: blur(20px);
	border-inline-end: 1px solid var(--gem-line);
}
#sidebar-chat-item.selected { background-color: var(--gem-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--gem-accent); }
.markdown-prose a { color: var(--gem-accent); text-decoration-color: var(--gem-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--gem-glow); }
html { scrollbar-color: var(--gem-line) transparent; }
::selection { background-color: var(--gem-mark); }

